import { createHash, randomBytes, timingSafeEqual } from "crypto";

/**
 * Agent secrets are generated by the server, shown to the user once and stored only as a
 * SHA-256 hash (`sha256:<hex>`). The secrets are 128-bit random values, so a fast unsalted hash
 * is sufficient — like API tokens, they can't be brute-forced from the hash.
 */
export class AgentSecrets {

    private static readonly HASH_PREFIX = "sha256:";

    /** A new random secret: 32 hex characters (128 bit). */
    static generate() {
        return randomBytes(16).toString("hex");
    }

    static hash(secret: string) {
        return this.HASH_PREFIX + createHash("sha256").update(secret, "utf8").digest("hex");
    }

    static isHash(value: string) {
        return value.startsWith(this.HASH_PREFIX) && /^[0-9a-f]{64}$/.test(value.slice(this.HASH_PREFIX.length));
    }

    /** Constant-time check of a secret against a stored hash. */
    static verify(secret: string, secretHash: string) {
        if (!this.isHash(secretHash)) return false;

        const expected = Buffer.from(secretHash.slice(this.HASH_PREFIX.length), "hex");
        const actual = createHash("sha256").update(secret, "utf8").digest();

        return timingSafeEqual(expected, actual);
    }

}
